        // This function is used to fetch the TransportStaff Details
        private String FetchDetailsFromDatabase(int aiTransportStaffId, int aiSchoolId,int aiAcademicYearId)
        {
            string sSelectStatement = " SELECT  " +
            "tblTransport.TransportStaffId" +
            ",tblTransport.SalutationId" +
            ",tblTransport.FirstName" +
            ",tblTransport.MiddleName" +
            ",tblTransport.LastName " +
            ",tblTransport.MobileNo " +
            ",tblTransport.Address "+
            ",tblTransport.DesignationId " +
            ",tblTransport.UserId" +
            ",tblTransport.SchoolId " +
            ",tblTransport.Academic_Year_Id " +
            ",tblTransport.Is_Deleted " +
            ",tblTransport.InsertDate" +
            ",tblTransport.InsertedById " +
            ",tblTransport.UpdateDate" +
            ",tblTransport.UpdatedById " +
            ",tblTransport.PhotoFilePath" +
            ",tblTransport.BinaryPhotoImage" +
            ",User_Master.EmergencyContactNumber "+
            ",User_Master.DOB" +
            " FROM [Transport].[TransportStaffMaster] tblTransport " +
            " INNER JOIN User_Master on "+
            " tblTransport.UserId=User_Master.User_Id " +
            " AND tblTransport.SchoolId=User_Master.School_Id "+
            " WHERE TransportStaffId=" + aiTransportStaffId +
            " AND SchoolId = " + aiSchoolId +
            " AND Academic_Year_Id = " + aiAcademicYearId +
            " AND tblTransport.Is_Deleted=0 " +
            " AND User_Master.Is_Deleted=N'N'";
            return sSelectStatement;
        }

